function syncPermissions(){for(const [id,permission]of Object.entries(roleControls))$(id).disabled=!contentAdmitted||busyControls.has($(id))||!identity?.permissions.includes(permission)||((id.startsWith('library-')||id.startsWith('claims-'))&&libraryBusy)||(id==='claims-prev'&&!claimsBack.length)||(id==='claims-next'&&!claimsNext)||(id==='library-prev'&&!libraryBack.length)||(id==='library-next'&&!libraryNext)||(id==='send'&&chatPending)||(id==='analyze-table'&&!['text/csv','text/tab-separated-values','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(selectedMetadata?.media_type))||(id==='assemble-source'&&!selectedSource)||(id==='browse-knowledge'&&(!selectedMetadata?.indexing?.ready))||(id.startsWith('knowledge-')&&(!knowledgeSource||knowledgeBusy))||(id==='knowledge-prev'&&knowledgeOffset===0)||(id==='knowledge-next'&&knowledgeNext===null)||(id==='knowledge-edge-prev'&&(!knowledgeNode||knowledgeEdgeOffset===0))||(id==='knowledge-edge-next'&&(!knowledgeNode||knowledgeEdgeNext===null))||(id==='share-source'&&(!accessState||accessState.document_id!==selectedSource))||(id==='retry-index'&&(!selectedMetadata?.can_manage_access||sourceIndexState?.state!=='failed'))||(id==='governed-prev'&&governedOffset===0)||(id==='governed-next'&&!governedHasNext);$('model').disabled=busyControls.has($('model'))||!(contentAdmitted&&modelReady&&identity?.permissions.includes('chat'))||chatPending;$('download-source').disabled=busyControls.has($('download-source'))||!selectedSource;syncOAuthControls();}
function guarded(fn){return async function(){const epoch=authEpoch;busyControls.add(this);this.disabled=true;try{await fn();}catch(e){if(epoch===authEpoch&&!['AbortError','StaleSessionError'].includes(e.name))notice(e.message,true);}finally{busyControls.delete(this);if(!roleControls[this.id]&&!['model','download-source'].includes(this.id))this.disabled=false;syncPermissions();}};}
