$('upload').onclick=guarded(async()=>{const result=await request('/v1/documents','POST',{title:$('docname').value,version:$('version').value,text:$('document').value});pretty('ingestion-evidence',result);notice(result.created?`Source stored. Indexing: ${result.indexing?.state||'awaiting qualification'}.`:'This exact revision is already present.');await refresh();});
$('upload-file').onclick=guarded(async()=>{const f=$('file').files[0];if(!f)throw Error('Choose a UTF-8 TXT, Markdown, CSV, TSV, JSON, XLSX, or PDF file.');if(f.size>uploadLimits.max_bytes)throw Error(`File exceeds ${uploadLimits.max_bytes/(1024*1024)} MiB.`);const form=new FormData();form.append('file',f);form.append('version',$('file-version').value);const result=await request('/v1/files','POST',form);pretty('ingestion-evidence',result);notice(`Source extracted. Indexing: ${result.indexing?.state||'awaiting qualification'}.`);await refresh();});
$('seed').onclick=guarded(async()=>{for(const [version,value]of [['1','85'],['2','75']])await request('/v1/documents','POST',{title:'Fictitious Pump-X supplier revision '+version,version,text:`SYNTHETIC DEMO · no company data\nPump-X maximum operating temperature is ${value} C`});await refresh();notice('Two synthetic revisions loaded. Review the conflict or ask a question.');});
$('sample-question').onclick=()=>{$('question').value='What is the Pump-X maximum operating temperature?';$('question').focus();};
async function ask(path){const question=$('question').value.trim();if(!question||chatPending)return;const epoch=authEpoch,scope=scopeEpoch,ownedSession=sessionId;chatPending=true;syncPermissions();append(question,'user');$('chat-status').textContent='Retrieving sources?';try{const body={question,session_id:ownedSession,request_id:crypto.randomUUID().replaceAll('-','')};if(chatScope.kind!=='library'){body.document_ids=[...chatScope.document_ids];body.revision=chatScope.revision;if(chatScope.pages)body.pages=[...chatScope.pages];}const result=await request(path,'POST',body);if(epoch!==authEpoch||scope!==scopeEpoch)return;sessionId=result.session_id;if($('question').value.trim()===question)$('question').value='';append(result.answer,'assistant',`${result.provider||result.mode} ? ${result.model||'source excerpts'} ? unverified answer`,result.citations);if(result.memory)pretty('memory-data',result.memory);renderAnswerTrace(result);$('chat-status').textContent='Sources are inspectable. Model answers cannot approve knowledge.';}catch(e){if(epoch!==authEpoch||scope!==scopeEpoch)return;if(!['AbortError','StaleSessionError'].includes(e.name))$('chat-status').textContent='Request failed. No answer was received; your question is retained. Check server receipts before retrying an inference attempt.';throw e;}finally{if(epoch===authEpoch&&scope===scopeEpoch){chatPending=false;syncPermissions();}}}
$('send').onclick=guarded(()=>ask('/v1/chat'));$('model').onclick=guarded(()=>ask('/v1/reason'));$('model').disabled=true;
$('download-source').onclick=guarded(async()=>{if(!selectedSource)return;const sequence=sourceEpoch,filename=safeFilename(selectedMetadata?.title,selectedMetadata?.media_type);const blob=await request('/v1/sources/'+selectedSource+'/original','GET',undefined,'blob');if(sequence!==sourceEpoch)return;const url=URL.createObjectURL(blob);downloadUrls.add(url);const a=node('a');a.href=url;a.download=filename;a.click();setTimeout(()=>{URL.revokeObjectURL(url);downloadUrls.delete(url);},1000);});
function memoryPath(ownedSession){const query=new URLSearchParams();if(chatScope.kind!=='library'){for(const id of chatScope.document_ids)query.append('document_ids',id);if(chatScope.revision!==undefined)query.set('revision',chatScope.revision);for(const page of chatScope.pages||[])query.append('pages',String(page));}const encoded=query.toString();return '/v1/memory/'+encodeURIComponent(ownedSession)+(encoded?'?'+encoded:'');}
function clearKnowledge(){$('knowledge-kind').value='all';$('knowledge-query').value='';knowledgeEpoch++;knowledgeSource=null;knowledgeArtifact=null;knowledgeOffset=0;knowledgeNext=null;knowledgeNode=null;knowledgeEdgeOffset=0;knowledgeEdgeNext=null;knowledgeBusy=false;knowledgeFilter={kind:'all',query:''};for(const id of ['knowledge-items','knowledge-detail','knowledge-relationships'])$(id).replaceChildren();$('knowledge-scope').textContent='Inspect a published source, then browse its knowledge.';$('knowledge-status').textContent='No source graph loaded.';$('knowledge-edge-status').textContent='Select a node to inspect its source lineage.';}
function checkKnowledgeSource(data){if(!knowledgeSource||data.source.document_id!==knowledgeSource.id||data.source.revision!==knowledgeSource.revision||data.source.source_sha256!==knowledgeSource.sha256||(knowledgeArtifact&&knowledgeArtifact!==data.source.artifact_sha256)){clearKnowledge();throw Error('Knowledge source or generation changed; inspect the source again.');}knowledgeArtifact=data.source.artifact_sha256;}
async function loadKnowledgePage(offset=0){if(!knowledgeSource)throw Error('Inspect a published source first.');const sequence=++knowledgeEpoch,source=sourceEpoch,id=knowledgeSource.id;knowledgeBusy=true;syncPermissions();try{const query=new URLSearchParams({kind:knowledgeFilter.kind,q:knowledgeFilter.query,offset:String(offset),limit:'25'});const data=await request('/v1/knowledge/'+encodeURIComponent(id)+'/browse?'+query);if(sequence!==knowledgeEpoch||source!==sourceEpoch||id!==selectedSource)return;checkKnowledgeSource(data);knowledgeOffset=data.offset;knowledgeNext=data.next_offset;$('knowledge-scope').textContent=`${knowledgeSource.title} · revision ${data.source.revision} · original SHA256 ${data.source.source_sha256}`;$('knowledge-status').textContent=`${data.items.length} of ${data.total} matching candidate nodes · ${data.summary.nodes} source nodes, ${data.summary.relationships} relationships, ${data.summary.formulas} formula candidates. Formula detection is not exhaustive.`;$('knowledge-items').replaceChildren(...data.items.map(item=>{const card=node('div',undefined,'card');card.append(node('strong',item.kind.replaceAll('_',' ')),node('p',item.excerpt),node('small',`${item.locator} · ${item.relationships} recorded relationships${item.omitted_characters?' · excerpt shortened by '+item.omitted_characters+' characters':''}`),action('Inspect node and relationships',()=>loadKnowledgeNode(item.id)));return card;}));if(!data.items.length)$('knowledge-items').textContent='No matching candidate nodes. This does not prove that no relevant knowledge or formulas exist.';}finally{if(sequence===knowledgeEpoch){knowledgeBusy=false;syncPermissions();}}}
