$('browse-knowledge').onclick=guarded(async()=>{if(!selectedSource||!selectedMetadata?.indexing?.ready)throw Error('Inspect a published source first.');clearKnowledge();knowledgeSource={id:selectedSource,title:selectedMetadata.title||selectedSource,revision:String(selectedMetadata.revision),sha256:selectedMetadata.original_sha256};$('knowledge-kind').value='all';$('knowledge-query').value='';view('review');await loadKnowledgePage();});
