 if(pdfRender)pdfRender.cancel();if(pdfTextLayer)pdfTextLayer.cancel();pdfRender=null;pdfTextLayer=null;
 $('pdf-text-layer').replaceChildren();$('pdf-quote-layer').replaceChildren();$('pdf-text').replaceChildren();
 const canvas=$('pdf-canvas');canvas.width=0;canvas.height=0;canvas.style.width='0px';canvas.style.height='0px';
