 canvas.style.width=geometry.width+'px';canvas.style.height=geometry.height+'px';
 pdfRender=page.render({canvasContext:canvas.getContext('2d'),viewport,transform:geometry.transform,annotationMode:0});
 try{await pdfRender.promise;}catch(e){if(e.name==='RenderingCancelledException')return;throw e;}
