function resetSourceAccess(){accessEpoch++;accessState=null;$('source-sharing').hidden=true;$('source-grants').replaceChildren();$('source-access-status').textContent='';$('share-target').value='';$('share-expiry').value='';$('share-kind').value='user';}
async function loadSourceAccess(documentId,sourceSequence=sourceEpoch){const sequence=++accessEpoch;const data=await request('/v1/sources/'+encodeURIComponent(documentId)+'/access');if(sequence!==accessEpoch||sourceSequence!==sourceEpoch||documentId!==selectedSource)return;accessState=data;$('source-sharing').hidden=false;$('source-access-status').textContent=`Private by default. Sharing revision ${data.epoch}.`;paged('source-grants',data.grants||[],grant=>{const card=node('div',undefined,'card');const expired=grant.expires_at&&Date.parse(grant.expires_at)<=Date.now();card.append(node('strong',grant.subject_id),node('small',`${grant.subject_kind} ? ${grant.revoked?'Revoked':expired?'Expired':'Read access'}${grant.expires_at?' ? expires '+new Date(grant.expires_at).toLocaleString():''}`));if(!grant.revoked&&!expired)card.append(action('Revoke read access',async()=>{if(!accessState||accessState.document_id!==documentId)throw Error('Reload sharing before changing access.');await applySourceShare({expected_epoch:accessState.epoch,subject_kind:grant.subject_kind,subject_id:grant.subject_id,revoke:true});}));return card;});syncPermissions();}
async function applySourceShare(change){if(!accessState||accessState.document_id!==selectedSource)throw Error('Select an owned source before sharing.');const documentId=selectedSource,sequence=sourceEpoch;try{await request('/v1/sources/'+encodeURIComponent(documentId)+'/access','POST',change);}catch(error){if(sequence===sourceEpoch&&documentId===selectedSource)await loadSourceAccess(documentId,sequence);throw error;}if(sequence!==sourceEpoch||documentId!==selectedSource)return;await loadSourceAccess(documentId,sequence);notice(change.revoke?'Read access revoked. Future requests require current permission.':'Read access granted.');}
$('share-source').onclick=guarded(async()=>{if(!accessState)throw Error('Select an owned source first.');const expiry=$('share-expiry').value;await applySourceShare({expected_epoch:accessState.epoch,subject_kind:$('share-kind').value,subject_id:$('share-target').value.trim(),expires_at:expiry?new Date(expiry).toISOString():null,revoke:false});});

function resetIndexStatus(){sourceIndexState=null;$('source-index-status').textContent='No processing status selected.';}
function renderIndexStatus(status){sourceIndexState=status||null;if(!status){$('source-index-status').textContent='Processing status is unavailable.';syncPermissions();return;}const progress=Number.isInteger(status.passages_total)?` ${status.passages_completed??0}/${status.passages_total} passages encoded.`:'';$('source-index-status').textContent=status.state==='ready'?(status.source_coverage_complete===false?'Index ready for available text. Source coverage is incomplete.':'Validated index ready for search.'):`${status.ready?'A previous validated index remains available. ':''}Indexing: ${status.state}.${progress}${status.error_code?' '+status.error_code+'.':''}${!status.ready?' This source is withheld from search until publication.':''}`;syncPermissions();}
function scheduleIndexRefresh(documents){if(indexPoll!==null)clearTimeout(indexPoll);indexPoll=null;if(!indexWorkerConfigured||!documents.some(doc=>doc.indexing?.job_id&&['queued','running'].includes(doc.indexing.state)))return;const epoch=authEpoch;indexPoll=setTimeout(()=>{indexPoll=null;if(epoch!==authEpoch||!token)return;refresh().catch(error=>{if(epoch===authEpoch&&!['AbortError','StaleSessionError'].includes(error.name))notice('Processing status refresh failed: '+error.message,true);});},5000);}
$('retry-index').onclick=guarded(async()=>{if(!selectedSource||!selectedMetadata?.can_manage_access||sourceIndexState?.state!=='failed')throw Error('Select an owned source with failed indexing.');const documentId=selectedSource,sequence=sourceEpoch;await request('/v1/sources/'+encodeURIComponent(documentId)+'/retry-index','POST',{expected_epoch:sourceIndexState.epoch});if(sequence!==sourceEpoch)return;const status=await request('/v1/sources/'+encodeURIComponent(documentId)+'/index');if(sequence!==sourceEpoch)return;renderIndexStatus(status);await refresh();notice('Indexing retry queued. Completed checkpoints are retained.');});


function renderClaim(claim){const card=node('div',undefined,'card');const badge=node('span',claim.status==='verified'?'human reviewed':claim.status,'status '+claim.status);card.append(badge,node('strong',`${claim.subject} · ${claim.predicate} = ${claim.value}`),node('small',`${claim.id} · revision ${claim.revision} · ${claim.locator}`));const buttons=node('div',undefined,'actions');buttons.append(action('View source',()=>inspect(claim.document_id,claim.locator)),action('Use for learning',async()=>{$('learning-claim').value=claim.id;view('memory');}));if(identity.permissions.includes('review')&&!['superseded','rejected'].includes(claim.status))for(const [label,decision]of [['Prefer this value','accept'],['Contest','contest'],['Reject','reject']])buttons.append(action(label,async()=>{const rationale=$('rationale').value.trim();if(rationale.length<10)throw Error('Provide a review rationale of at least 10 characters.');const result=await request('/v1/review/'+claim.id,'POST',{decision,expected_revision:claim.revision,rationale});notice('Review recorded: '+result.state+' · '+result.audit_receipt.slice(0,12));await refresh();}));card.append(buttons);return card;}
function renderClaims(c){
 claimsNext=c.next_cursor||null;
 const summary=c.summary||{};
 $('verified-count').textContent=summary.verified_claims??'\u2014';
 $('conflict-count').textContent=summary.active_conflict_groups??'\u2014';
 $('claims-status').textContent=`${c.total??'?'} authorized claims; ${c.items.length} shown. Pages reflect current access.`;
 $('conflicts').textContent=summary.conflict_analysis_complete!==true?(summary.warning||'Conflict analysis is unavailable.'):
  c.conflicts.length?c.conflicts.map(g=>`${g.subject} / ${g.predicate}: ${Object.keys(g.alternatives).join(' vs ')}`).join('\n'):
  'No active conflicting claim groups. Historical alternatives are retained.';
 if(summary.active_conflict_groups>c.conflicts.length)$('conflicts').textContent+=`\nShowing ${c.conflicts.length} of ${summary.active_conflict_groups} conflicting groups.`;
 $('claims').replaceChildren();for(const claim of c.items)$('claims').append(renderClaim(claim));
}
$('claims-next').onclick=guarded(async()=>{if(!claimsNext)return;claimsBack.push(claimsCursor);claimsCursor=claimsNext;await refresh();});
$('claims-prev').onclick=guarded(async()=>{if(!claimsBack.length)return;claimsCursor=claimsBack.pop();await refresh();});

$('load-cost-demo').onclick=guarded(async()=>{pretty('cost-demo-data',await request('/v1/admin/costs'));notice('Cost governance example loaded. Cash spending remains disabled.');});

function syncOAuthControls(){for(const provider of ['google','github'])for(const mode of ['login','signup','link']){const control=$('oauth-'+provider+'-'+mode);control.disabled=authBusy>0||busyControls.has(control)||!authProviders[provider]||(mode==='link'?identity?.identity_kind!=='local-user':Boolean(identity));}}

async function authRequest(path,method='GET',body,csrf,linkToken){
 const epoch=authEpoch,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);pendingRequests.add(controller);
 const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(csrf)headers['X-CSRF-Token']=csrf;if(linkToken)headers.Authorization='Bearer '+linkToken;if(identity?.actor)headers['X-NSAI-Expected-Actor']=identity.actor;
 try{const response=await fetch(path,{method,headers,credentials:'same-origin',signal:controller.signal,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(epoch!==authEpoch){const error=Error('Authentication changed');error.name='StaleSessionError';throw error;}if(!response.ok){const error=Error(typeof data.detail==='string'?data.detail:'Authentication unavailable');error.status=response.status;if(response.status===401&&identity){clearWorkspace();notice('Authentication changed. Private workspace cleared.',true);error.name='StaleSessionError';}throw error;}return data;}finally{clearTimeout(timeout);pendingRequests.delete(controller);}
}

async function clearBrowserLogin(){const config=await authRequest('/auth/config');authProviders=config.providers;if(config.csrf){await authRequest('/auth/logout','POST',undefined,config.csrf);authChannel?.postMessage('changed');}csrfToken='';syncOAuthControls();}

async function beginProvider(provider,mode){
 authBusy++;syncOAuthControls();const epoch=authEpoch;
 try{const config=await authRequest('/auth/config');authProviders=config.providers;const result=await authRequest('/auth/'+provider+'/start','POST',{mode},config.csrf,mode==='link'?token:undefined);if(epoch!==authEpoch)return;const destination=new URL(result.authorization_url);const expected=provider==='google'?'https://accounts.google.com':'https://github.com';if(destination.origin!==expected||destination.username||destination.password||destination.searchParams.get('code_challenge_method')!=='S256')throw Error('Invalid provider authorization destination');if(mode!=='link')clearWorkspace();window.location.assign(destination.href);}finally{authBusy--;syncOAuthControls();}
}

for(const provider of ['google','github'])for(const mode of ['login','signup','link'])$('oauth-'+provider+'-'+mode).onclick=guarded(async()=>beginProvider(provider,mode));

async function initializeOAuth(){
 const epoch=authEpoch;let ownedEpoch=epoch;const address=new URL(window.location.href),result=address.searchParams.get('auth');
 if(['complete','cancelled','failed'].includes(result)){address.searchParams.delete('auth');window.history.replaceState(null,'',address.pathname+address.search+address.hash);}
 try{
  const config=await authRequest('/auth/config');authProviders=config.providers;syncOAuthControls();
  $('oauth-status').textContent=Object.values(authProviders).some(Boolean)?'Sign in, create an account, or explicitly link a provider to an individual identity.':'Provider sign-in is not configured. Local credentials remain available.';
  if(epoch!==authEpoch||identity||token||!config.csrf)return;
  let session;try{session=await authRequest('/auth/session');}catch(error){if(error.status===401)return;throw error;}
  if(epoch!==authEpoch)return;
  clearWorkspace();ownedEpoch=authEpoch;authMode='cookie';csrfToken=session.csrf;
  const capabilities=await request('/v1/capabilities');
  if(capabilities.identity.actor!==session.identity.actor){clearWorkspace();throw Error('Browser identity changed; sign in again.');}
  await adoptIdentity(capabilities);
  $('oauth-status').textContent='Browser session connected. Provider linking is explicit; ownership and permissions stay with this account.';
  if(result==='complete')authChannel?.postMessage('changed');
 }catch(error){if(ownedEpoch===authEpoch&&!['AbortError','StaleSessionError'].includes(error.name)){if(authMode==='cookie'&&!identity){clearWorkspace();ownedEpoch=authEpoch;}$('oauth-status').textContent='Provider sign-in unavailable. Local credentials remain available.';}}
 finally{if(ownedEpoch===authEpoch){if(result==='cancelled')$('oauth-status').textContent='Provider authorization was cancelled. Existing account access was preserved.';if(result==='failed')$('oauth-status').textContent='Provider authorization failed or expired. Try again, or create an account before signing in.';}syncOAuthControls();}
}
initializeOAuth();

function clearTableAnalysis(){
 $('table-analysis').hidden=true;
 for(const id of ['table-chart','table-results','table-analysis-receipt'])$(id).replaceChildren();
 $('table-analysis-status').textContent='Choose columns to analyze this source revision.';
 $('table-sheet').replaceChildren(new Option('Select worksheet when needed',''));$('table-sheet').disabled=true;$('table-value-column').value='1';$('table-group-column').value='';$('table-skip-rows').value='0';$('table-operation').value='sum';$('table-unit').value='';
}
function renderTableAnalysis(data){
 const coverage=data.coverage;
 $('table-analysis-status').textContent=`${data.request.operation}: ${coverage.included_records} included / ${coverage.selected_records} selected records; ${coverage.excluded_records} empty or absent values excluded; ${coverage.skipped_records} header records skipped. Revision ${data.revision}.${data.worksheet?' Worksheet '+data.worksheet.name+' ('+data.worksheet.state+').':''}`;
 const table=node('table'),head=node('thead'),header=node('tr');
 for(const label of ['Group','Exact decimal result','Included records'])header.append(node('th',label));head.append(header);table.append(head);
 const body=node('tbody');for(const group of data.groups){const row=node('tr');row.append(node('td',group.label),node('td',group.value),node('td',String(group.included_records)));body.append(row);}table.append(body);$('table-results').replaceChildren(table);
 const target=$('table-chart');target.replaceChildren();
 if(!data.groups.length){target.append(node('p','No nonempty values remain. No numeric chart was generated.'));}
 else{
  const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');
  const height=60+data.groups.length*32;svg.setAttribute('viewBox',`0 0 600 ${height}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',`${data.request.operation} by group; ${data.unit.label||'unit not supplied'}. Exact decimal values are in the adjacent table.`);
  const values=data.groups.map(group=>Number(group.value));
  if(values.some(value=>!Number.isFinite(value)))throw Error('Numeric chart range is unavailable; exact results remain in the table.');
  const low=Math.min(0,...values),high=Math.max(0,...values),range=high-low||1,x=value=>190+(value-low)/range*390;
  const shape=(tag,attrs,text)=>{const item=document.createElementNS(ns,tag);for(const [key,value]of Object.entries(attrs))item.setAttribute(key,String(value));if(text!==undefined)item.textContent=text;svg.append(item);return item;};
  shape('title',{},`${data.request.operation}; ${data.unit.label||'unit not supplied'}. Display positions use browser number precision; the table preserves exact decimal results.`);
  shape('text',{x:10,y:20,'font-size':13},`${data.request.operation} (${data.unit.label||'unit not supplied'})`);
  shape('line',{x1:x(0),x2:x(0),y1:35,y2:height-10,stroke:'#596650'});
  data.groups.forEach((group,index)=>{const y=40+index*32,value=values[index];shape('text',{x:10,y:y+15,'font-size':12},group.label.length>24?group.label.slice(0,23)+'?':group.label);const bar=shape('rect',{x:Math.min(x(0),x(value)),y,width:Math.abs(x(value)-x(0)),height:20,fill:value<0?'#936448':'#557c36'});const title=document.createElementNS(ns,'title');title.textContent=`${group.label}: ${group.value}`;bar.append(title);});target.append(svg);
 }
 pretty('table-analysis-receipt',data);
}
$('analyze-table').onclick=guarded(async()=>{
 const source=selectedSource,sequence=sourceEpoch;
 if(!source||!['text/csv','text/tab-separated-values','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(selectedMetadata?.media_type))throw Error('Inspect a CSV, TSV or XLSX source first.');
 for(const id of ['table-chart','table-results','table-analysis-receipt'])$(id).replaceChildren();
 $('table-analysis-status').textContent='Validating source cells and calculating?';
 const payload={sheet:$('table-sheet').value||null,value_column:Number($('table-value-column').value),operation:$('table-operation').value,group_column:$('table-group-column').value===''?null:Number($('table-group-column').value),skip_rows:Number($('table-skip-rows').value),unit:$('table-unit').value};
 try{const data=await request('/v1/sources/'+encodeURIComponent(source)+'/analysis','POST',payload);if(source!==selectedSource||sequence!==sourceEpoch)return;renderTableAnalysis(data);}
 catch(error){if(source===selectedSource&&sequence===sourceEpoch)$('table-analysis-status').textContent='Analysis unavailable. Check column selection, header skip and explicit decimal values; no partial result is shown.';throw error;}
});
